import { computed } from "@angular/core";
import {
  patchState,
  signalStore,
  withComputed,
  withMethods,
  withState,
} from "@ngrx/signals";
import type {
  EventSnapshot,
  IssueSnapshot,
  ScoreSnapshot,
  SnapshotWithScore,
  TimeSnapshot,
} from "./engine-api.service";
import type { ActiveDecision, ScenarioContext } from "./decision-api.service";
import type { ScoreChange } from "./generated/state-changes.types";
import { formatTimeMs } from "./format-time";

export interface ParticipantPresence {
  id: string;
  display_name: string;
  role: string | null;
  connected: boolean;
}

interface ScoreState {
  totalScore: number;
  turnNumber: number;
  nextDecisionTimeMs: number;
  penaltyMs: number;
}

interface ExerciseState {
  exerciseId: number | null;
  title: string;
  phase: string;
  gameMode: string;
  practiceMode: boolean;
  playTimeMs: number;
  realTimeMs: number;
  speedFactor: number;
  paused: boolean;
  events: EventSnapshot[]; // domain: "injects"
  issues: IssueSnapshot[]; // domain: "defects"
  decisions: ActiveDecision[];
  participants: ParticipantPresence[];
  context: ScenarioContext | null;
  participantId: string;
  playerRole: string;
  playerType: string;
  score: ScoreState | null;
  loading: boolean;
  error: string | null;
}

const initialState: ExerciseState = {
  exerciseId: null,
  title: "",
  phase: "setup",
  gameMode: "classic",
  practiceMode: false,
  playTimeMs: 0,
  realTimeMs: 0,
  speedFactor: 1,
  paused: true,
  events: [],
  issues: [],
  decisions: [],
  participants: [],
  context: null,
  participantId: "",
  playerRole: "player",
  playerType: "advisor",
  score: null,
  loading: false,
  error: null,
};

export const ExerciseStore = signalStore(
  withState(initialState),

  withComputed((store) => ({
    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
    activeEvents: computed(() =>
      store.events().filter((e) => e.lifecycle === "running"),
    ), // active injects
    scheduledEvents: computed(() =>
      store.events().filter((e) => e.lifecycle === "scheduled"),
    ), // scheduled injects
    completedEvents: computed(() =>
      store.events().filter((e) => e.lifecycle === "completed"),
    ), // completed injects
    activeIssues: computed(() =>
      store.issues().filter((i) => i.lifecycle === "active"),
    ), // active defects
    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
    decisionCountdownMs: computed(() => {
      const decision = store
        .decisions()
        .find((d) => d.status === "open" && d.timeout_ms > 0);
      if (!decision) return null;
      const factor = store.speedFactor() || 1;
      const openedAtRt = decision.opened_at_pt_ms / factor;
      const elapsed = store.realTimeMs() - openedAtRt;
      return Math.max(0, decision.timeout_ms - elapsed);
    }),
    issuesWithCountdown: computed(() => {
      const pt = store.playTimeMs();
      return store
        .issues()
        .filter(
          (i) =>
            i.lifecycle === "active" &&
            i.auto_resolve_ms > 0 &&
            i.activated_at_pt_ms !== null,
        )
        .map((i) => {
          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
          return { ...i, remaining_ms: remaining };
        });
    }),
    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
    openDecisions: computed(() =>
      store.decisions().filter((d) => d.status === "open"),
    ),
    hasOpenDecision: computed(
      () => store.decisions().filter((d) => d.status === "open").length > 0,
    ),
    connectedParticipants: computed(() =>
      store.participants().filter((p) => p.connected),
    ),
    connectedCount: computed(
      () => store.participants().filter((p) => p.connected).length,
    ),
    isCollaborative: computed(
      () => store.gameMode() === "simple_collaborative",
    ),
    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
    isPracticeMode: computed(() => store.practiceMode()),
    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
      switch (store.phase()) {
        case "running":
          return "default";
        case "paused":
          return "secondary";
        case "completed":
          return "destructive";
        default:
          return "secondary";
      }
    }),
  })),

  withMethods((store) => ({
    setExerciseId(id: number): void {
      patchState(store, { exerciseId: id });
    },

    applySnapshot(snapshot: SnapshotWithScore): void {
      patchState(store, {
        exerciseId: snapshot.exercise_id,
        title: snapshot.title,
        phase: snapshot.phase,
        playTimeMs: snapshot.time.play_time_ms,
        realTimeMs: snapshot.time.real_time_ms,
        speedFactor: snapshot.time.factor,
        paused: snapshot.time.paused,
        events: snapshot.events,
        issues: snapshot.issues,
        decisions: snapshot.decisions ?? store.decisions(),
        score: snapshot.score
          ? {
              totalScore: snapshot.score.total_score,
              penaltyMs: snapshot.score.penalty_ms,
              turnNumber: snapshot.score.turn_number,
              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
            }
          : store.score(),
        loading: false,
        error: null,
      });
    },

    applyTimeUpdate(time: TimeSnapshot): void {
      patchState(store, {
        playTimeMs: time.play_time_ms,
        realTimeMs: time.real_time_ms,
        speedFactor: time.factor,
        paused: time.paused,
      });
    },

    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
    tick(wallDeltaMs: number): void {
      if (store.paused()) return;
      const factor = store.speedFactor();
      patchState(store, {
        realTimeMs: store.realTimeMs() + wallDeltaMs,
        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
      });
    },

    applyPhaseChange(phase: string): void {
      patchState(store, { phase });
    },

    updateEvent(eventId: string, lifecycle: string): void {
      const events = store
        .events()
        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
      patchState(store, { events });
    },

    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
      const issues = store
        .issues()
        .map((i) =>
          i.id === issueId
            ? { ...i, lifecycle, released: released ?? i.released }
            : i,
        );
      patchState(store, { issues });
    },

    setLoading(loading: boolean): void {
      patchState(store, { loading });
    },

    setError(error: string): void {
      patchState(store, { error, loading: false });
    },

    applyDecisions(decisions: ActiveDecision[]): void {
      patchState(store, { decisions });
    },

    setContext(ctx: ScenarioContext): void {
      patchState(store, { context: ctx });
    },

    setParticipantId(id: string): void {
      patchState(store, { participantId: id });
    },

    setPlayerRole(role: string): void {
      patchState(store, { playerRole: role });
    },

    closeDecision(decisionId: string): void {
      const decisions = store
        .decisions()
        .map((d) => (d.id === decisionId ? { ...d, status: "closed" } : d));
      patchState(store, { decisions });
    },

    updatePresence(participants: ParticipantPresence[]): void {
      patchState(store, { participants });
    },

    setGameMode(mode: string): void {
      patchState(store, { gameMode: mode });
    },

    setPracticeMode(practice: boolean): void {
      patchState(store, { practiceMode: practice });
    },

    setPlayerType(playerType: string): void {
      patchState(store, { playerType });
    },

    setSpeedFactor(factor: number): void {
      patchState(store, { speedFactor: factor });
    },

    applyScoreChange(change: Pick<ScoreChange, "total_score" | "penalty_ms" | "next_decision_time_ms" | "turn_number">): void {
      patchState(store, {
        score: {
          totalScore: change.total_score,
          penaltyMs: change.penalty_ms,
          nextDecisionTimeMs: change.next_decision_time_ms,
          turnNumber: change.turn_number,
        },
      });
    },

    applyRecommendation(
      decisionId: string,
      participantId: string,
      optionId: string,
    ): void {
      const decisions = store.decisions().map((d) =>
        d.id === decisionId
          ? {
              ...d,
              recommendations: {
                ...d.recommendations,
                [participantId]: optionId,
              },
            }
          : d,
      );
      patchState(store, { decisions });
    },
  })),
);

#!/usr/bin/env python3
"""Generate TypeScript interfaces from Python TypedDicts and Pydantic models.

Usage:
    python apps/tfc/codegen/generate-types.py

Reads:
    - apps/tfc/backend/engine/state_changes.py (TypedDicts)
Writes:
    - apps/tfc/frontend/src/app/core/generated/state-changes.types.ts
"""

from __future__ import annotations

import ast
import re
import sys
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]  # apps/tfc/
BACKEND = ROOT / "backend"
FRONTEND = ROOT / "frontend/src/app/core/generated"

HEADER = '''\
// @generated — DO NOT EDIT. Regenerate with: python apps/tfc/codegen/generate-types.py
// Source: {source}
'''

# Python type → TypeScript type mapping
TYPE_MAP: dict[str, str] = {
    "str": "string",
    "int": "number",
    "float": "number",
    "bool": "boolean",
    "None": "null",
}


def py_type_to_ts(annotation: ast.expr) -> str:
    """Convert a Python type annotation AST node to a TypeScript type string."""
    if isinstance(annotation, ast.Constant):
        if annotation.value is None:
            return "null"
        return str(annotation.value)

    if isinstance(annotation, ast.Name):
        name = annotation.id
        if name in TYPE_MAP:
            return TYPE_MAP[name]
        # Reference to another TypedDict — keep the name
        return name

    if isinstance(annotation, ast.Attribute):
        # e.g., typing.Optional — shouldn't appear with __future__ annotations
        return "unknown"

    if isinstance(annotation, ast.Subscript):
        base = annotation.slice
        if isinstance(annotation.value, ast.Name):
            container = annotation.value.id
            if container == "list":
                inner = py_type_to_ts(base)
                return f"{inner}[]"
            if container == "dict":
                if isinstance(base, ast.Tuple) and len(base.elts) == 2:
                    key = py_type_to_ts(base.elts[0])
                    val = py_type_to_ts(base.elts[1])
                    return f"Record<{key}, {val}>"
            if container == "Optional":
                inner = py_type_to_ts(base)
                return f"{inner} | null"
        return "unknown"

    if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
        left = py_type_to_ts(annotation.left)
        right = py_type_to_ts(annotation.right)
        return f"{left} | {right}"

    return "unknown"


def extract_typeddict_literal_type(comment: str | None) -> str | None:
    """Extract a literal type hint from a comment like '# "phase_change"'."""
    if not comment:
        return None
    match = re.search(r'"([^"]+)"', comment)
    return match.group(1) if match else None


def parse_typeddicts(source_path: Path) -> list[dict]:
    """Parse all TypedDict classes from a Python source file."""
    source = source_path.read_text()
    tree = ast.parse(source)
    source_lines = source.splitlines()

    results = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        # Check if it inherits from TypedDict
        is_typeddict = any(
            (isinstance(b, ast.Name) and b.id == "TypedDict")
            for b in node.bases
        )
        if not is_typeddict:
            continue

        fields = []
        for item in node.body:
            if isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name):
                field_name = item.target.id
                ts_type = py_type_to_ts(item.annotation)

                # Check for literal type hint in inline comment
                line = source_lines[item.lineno - 1] if item.lineno <= len(source_lines) else ""
                comment_match = re.search(r"#\s*(.+)$", line)
                comment = comment_match.group(1) if comment_match else None
                literal = extract_typeddict_literal_type(comment)
                if literal and field_name == "type":
                    ts_type = f'"{literal}"'

                fields.append((field_name, ts_type))

        results.append({
            "name": node.name,
            "fields": fields,
            "docstring": ast.get_docstring(node),
        })

    return results


def parse_union_alias(source_path: Path) -> dict[str, list[str]] | None:
    """Parse type alias unions like StateChange = PhaseChange | EventChange | ..."""
    source = source_path.read_text()
    tree = ast.parse(source)

    unions = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            target = node.targets[0]
            if isinstance(target, ast.Name) and isinstance(node.value, ast.BinOp):
                # Collect all members of a | chain
                members = []
                def collect_bitor(n: ast.expr) -> None:
                    if isinstance(n, ast.BinOp) and isinstance(n.op, ast.BitOr):
                        collect_bitor(n.left)
                        collect_bitor(n.right)
                    elif isinstance(n, ast.Name):
                        members.append(n.id)
                collect_bitor(node.value)
                if members:
                    unions[target.id] = members

    return unions if unions else None


def emit_typescript(typeddicts: list[dict], unions: dict[str, list[str]] | None, source_rel: str) -> str:
    """Emit TypeScript source from parsed TypedDicts."""
    lines = [HEADER.format(source=source_rel)]

    for td in typeddicts:
        if td["docstring"]:
            lines.append(f"/** {td['docstring']} */")
        lines.append(f"export interface {td['name']} {{")
        for field_name, ts_type in td["fields"]:
            lines.append(f"  {field_name}: {ts_type};")
        lines.append("}\n")

    if unions:
        for name, members in unions.items():
            lines.append(f"export type {name} =")
            for i, member in enumerate(members):
                prefix = "  | " if i > 0 else "  "
                suffix = ";" if i == len(members) - 1 else ""
                lines.append(f"{prefix}{member}{suffix}")
            lines.append("")

    return "\n".join(lines)


def main() -> None:
    # Parse state_changes.py
    state_changes_path = BACKEND / "engine" / "state_changes.py"
    if not state_changes_path.exists():
        print(f"Error: {state_changes_path} not found", file=sys.stderr)
        sys.exit(1)

    typeddicts = parse_typeddicts(state_changes_path)
    unions = parse_union_alias(state_changes_path)
    source_rel = "apps/tfc/backend/engine/state_changes.py"

    # Ensure output directory exists
    FRONTEND.mkdir(parents=True, exist_ok=True)

    # Write state-changes.types.ts
    output_path = FRONTEND / "state-changes.types.ts"
    ts_source = emit_typescript(typeddicts, unions, source_rel)
    output_path.write_text(ts_source)
    print(f"Generated {output_path.relative_to(ROOT)}")


if __name__ == "__main__":
    main()

